CANONICAL = ('preparation.json', 'A-entries.json', 'C-entries.json', 'bottom-rows.json',
             'candidates-nonzero.json', 'candidates-zero.json', 'classification.json', 'survivors.json')
COUNTS = ('a_count', 'c_count', 'bottom_rows', 'nonzero_candidates', 'zero_candidates',
          'candidate_count', 'survivor_count', 'classification_digest', 'c_zero_audit')


def digest(path):
    h = hashlib.sha256()
    with path.open('rb') as stream:
        for block in iter(lambda: stream.read(1024**2), b''):
            h.update(block)
    return h.hexdigest()


def read(path):
    return json.loads(path.read_text())


def checked_sources():
    for relative, expected in SOURCE_PINS.items():
        path = ROOT / relative
        if not relative.startswith(('certificates/', 'independent/')) or not path.resolve().is_relative_to(ROOT):
            raise ValueError('Nonportable source path')
        if path.is_symlink() or digest(path) != expected:
            raise ValueError('Source/data changed: ' + relative)
    return SOURCE_PINS


def validate_complete(result, directory, expected, label):
    if result.get('status') != 'FULL_GEOMETRY_DISCOVERY_COMPLETE':
        raise ValueError('Fresh complete geometry is required')
    if result.get('point_label') != label or result.get('backend') != BACKEND:
        raise ValueError('Result identity mismatch')
    if any(result.get(k) is not True for k in
           ('assertions_enabled', 'sources_unchanged', 'executable_unchanged', 'witness_plan_unchanged')):
        raise ValueError('Missing unchanged-source/runtime/plan guards')
    observed = {name: digest(directory / name) for name in CANONICAL}
    if observed != result.get('canonical_artifact_sha256') or observed != expected['canonical_artifact_sha256']:
        raise ValueError('Complete canonical artifacts differ from frozen expectations')
    if any(result.get(key) != expected['counts'][key] for key in COUNTS):
        raise ValueError('Complete counts/classification differ from frozen expectations')
    if result['survivor_count'] != 0 or read(directory / 'survivors.json') != []:
        raise ValueError('Survivors cannot produce an exclusion certificate')
    return observed


def invoke_kernel(label, output, plan, prepare_only):
    spec = importlib.util.spec_from_file_location('continuous_v82_' + BACKEND, ROOT / KERNEL)
    kernel = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(kernel)
    if BACKEND == 'primary':
        kernel.run_point(label, output, prepare_only, plan)
    else:
        old = sys.argv
        sys.argv = [str(ROOT / KERNEL), '--point', label, '--output', str(output), '--witness-plan', str(plan)]
        if prepare_only:
            sys.argv.append('--prepare-only')
        try:
            kernel.main()
        finally:
            sys.argv = old


def install_default_cpu_limit(selection, label):
    """Apply the frozen batch cap only to a wholly unrestricted process."""
    key = 'control_cpu_seconds' if label in selection['controls'] else 'point_cpu_seconds'
    soft = selection['caps'][key]
    if type(soft) is not int or not 1 <= soft <= 7200:
        raise ValueError('Invalid frozen default CPU cap')
    inherited = resource.getrlimit(resource.RLIMIT_CPU)
    if inherited == (resource.RLIM_INFINITY, resource.RLIM_INFINITY):
        resource.setrlimit(resource.RLIMIT_CPU, (soft, soft + 1))
    return resource.getrlimit(resource.RLIMIT_CPU)


def execute(label, output, prepare_only=False):
    if not __debug__:
        raise ValueError('Assertions must be enabled')
    checked_sources()
    own_hash = digest(Path(__file__))
    executable = Path(sys.executable).resolve()
    executable_hash = digest(executable)
    selection = read(ROOT / DATA / 'selection.json')
    if label not in selection['labels'] + selection['controls']:
        raise ValueError('Point outside this exact frozen batch')
    if output.exists():
        raise FileExistsError('Refusing to overwrite an artifact directory')
    plan = ROOT / DATA / 'plans' / (label.lower().replace(':', '-') + '.json')
    plan_hash = digest(plan)
    install_default_cpu_limit(selection, label)
    # Expected geometry data is deliberately not parsed before fresh enumeration.
    invoke_kernel(label, output, plan, prepare_only)
    result = read(output / 'result.json')
    if result.get('point_label') != label or result.get('backend') != BACKEND or any(result.get(k) is not True for k in
           ('assertions_enabled', 'sources_unchanged', 'executable_unchanged', 'witness_plan_unchanged')):
        raise ValueError('Kernel identity/guard mismatch')
    if result.get('runtime', {}).get('python_sha256') != executable_hash:
        raise ValueError('Kernel runtime binding mismatch')
    if prepare_only:
        if result.get('status') != 'PREPARATION_ONLY' or result.get('point_label') != label:
            raise ValueError('Preparation result mismatch')
        status = 'PREPARATION_ONLY_NO_GEOMETRY'
        canonical = {}
    else:
        expected = read(ROOT / DATA / 'expected.json')['points'][label]
        canonical = validate_complete(result, output, expected, label)
        status = 'POINT_PASS'
    checked_sources()
    if digest(Path(__file__)) != own_hash or digest(executable) != executable_hash or Path(sys.executable).resolve() != executable:
        raise ValueError('Frontend/runtime changed during replay')
    if digest(plan) != plan_hash or result.get('input_witness_plan_sha256') != plan_hash:
        raise ValueError('Frozen witness plan changed or was not used')
    if result.get('driver_sha256') != SOURCE_PINS[KERNEL]:
        raise ValueError('Wrong relocated kernel')
    record = {'schema_version': 1, 'status': status, 'point_label': label, 'backend': BACKEND,
              'previously_certified_control': label in selection['controls'],
              'scope': 'EXACT_FROZEN_LABEL_REPLAY_NO_AUTOMATIC_THEOREM_PROMOTION',
              'frontend_sha256': own_hash, 'source_sha256': SOURCE_PINS,
              'kernel_result_sha256': digest(output / 'result.json'),
              'canonical_artifact_sha256': canonical, 'plan_sha256': plan_hash,
              'python_sha256': executable_hash, 'cpu_limits_seconds': list(resource.getrlimit(resource.RLIMIT_CPU)),
              'sources_unchanged': True, 'executable_unchanged': True, 'witness_plan_unchanged': True}
    if not prepare_only:
        record['counts'] = {key: result[key] for key in COUNTS}
    with (output / 'certificate-result.json').open('x') as stream:
        json.dump(record, stream, sort_keys=True, separators=(',', ':'))
        stream.write('\n')
    print(status + ' ' + json.dumps(record, sort_keys=True), flush=True)
    return record


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--point')
    parser.add_argument('--output', type=Path)
    modes = parser.add_mutually_exclusive_group()
    modes.add_argument('--prepare-only', action='store_true')
    modes.add_argument('--check-sources', action='store_true')
    args = parser.parse_args()
    if not __debug__:
        parser.error('Assertions must be enabled')
    checked_sources()
    if args.check_sources:
        print('PASS_SOURCE_CHECK_ONLY ' + json.dumps({'source_sha256': SOURCE_PINS,
              'frontend_sha256': digest(Path(__file__)), 'selection': read(ROOT / DATA / 'selection.json')}, sort_keys=True))
        return
    if args.point is None:
        parser.error('--point is required')
    if args.output is None:
        with tempfile.TemporaryDirectory(prefix='continuous-v82-') as temporary:
            execute(args.point, Path(temporary) / 'artifacts', args.prepare_only)
    else:
        execute(args.point, args.output.resolve(), args.prepare_only)


if __name__ == '__main__':
    main()
